// ---- Data embedded from maternal_health.xlsx (sheet: District Data) ----
const SHEET_DistrictData={name:'District Data',
 columns:['district','year','pregnancies_registered','institutional_deliveries','postnatal_check_48h'],
 rows:[
  ['Gaya',2021,1000,680,600],['Gaya',2022,1100,792,693],['Gaya',2023,1200,900,816],
  ['Nalanda',2021,900,675,630],['Nalanda',2022,1000,780,720],['Nalanda',2023,1100,880,825],
  ['Purnia',2021,1200,720,660],['Purnia',2022,1300,819,728],['Purnia',2023,1400,924,812]
]};
// ---- Data embedded from maternal_health.xlsx (sheet: Indicator Notes) ----
const SHEET_IndicatorNotes={name:'Indicator Notes',
 columns:['indicator','definition','formula','unit','source'],
 rows:[
  ['Institutional delivery coverage','Share of registered pregnancies with an institutional delivery','institutional_deliveries / pregnancies_registered * 100','percent','synthetic maternal-health workbook fixture'],
  ['Postnatal check within 48 hours coverage','Share of registered pregnancies with a recorded postnatal check within 48 hours','postnatal_check_48h / pregnancies_registered * 100','percent','synthetic maternal-health workbook fixture'],
  ['Important','Illustrative benchmark data; not official statistics and not person-level records',null,null,'synthetic maternal-health workbook fixture']
]};

// ---- Derived lookups ----
const COLS=SHEET_DistrictData.columns, idx=c=>COLS.indexOf(c), val=(r,c)=>r[idx(c)];
const YEARS=[...new Set(SHEET_DistrictData.rows.map(r=>r[1]))].sort((a,b)=>a-b);
const DISTRICTS=[...new Set(SHEET_DistrictData.rows.map(r=>r[0]))].sort();
// Indicators are parsed from the "formula" column of Indicator Notes: "<num> / <den> * 100"
const INDICATORS=SHEET_IndicatorNotes.rows.filter(r=>r[3]==='percent').map(r=>{
  const parts=r[2].split(' / ');
  return{label:r[0],definition:r[1],formula:r[2],unit:r[3],source:r[4],
         numerator:parts[0].trim(),denominator:parts[1].split(' * ')[0].trim()};
});
const WARN=SHEET_IndicatorNotes.rows.find(r=>r[0]==='Important');
const $=id=>document.getElementById(id);
const state={ind:0,year:YEARS[YEARS.length-1]};
const cov=(r,ind)=>{const n=val(r,ind.numerator),d=val(r,ind.denominator);return d?n/d*100:null;};
const fmtPct=v=>v==null?'—':v.toFixed(1)+'%';
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

// ---- Controls ----
$('disclaimer').textContent='⚠ '+WARN[1];
const indSel=$('indicatorSel'),yearSel=$('yearSel');
INDICATORS.forEach((ind,i)=>indSel.add(new Option(ind.label,i)));
yearSel.add(new Option('All years (trend)','all'));
YEARS.forEach(y=>yearSel.add(new Option(y,y)));
indSel.value=String(state.ind);
yearSel.value=String(state.year);
indSel.onchange=()=>{state.ind=+indSel.value;render();};
yearSel.onchange=()=>{state.year=yearSel.value==='all'?'all':+yearSel.value;render();};

// ---- Rendering ----
function renderComparison(ind){
  const box=$('comparison');
  if(state.year==='all'){
    let h='<table><tr><th>District</th>'+YEARS.map(y=>`<th class="num">${y}</th>`).join('')+'<th class="num">avg</th></tr>';
    DISTRICTS.forEach(d=>{
      const rows=SHEET_DistrictData.rows.filter(r=>r[0]===d).sort((a,b)=>a[1]-b[1]);
      const vs=rows.map(r=>cov(r,ind));
      const avg=vs.reduce((s,v)=>s+v,0)/vs.length;
      h+=`<tr><td><strong>${esc(d)}</strong></td>`
        +vs.map(v=>`<td class="num">${fmtPct(v)}<div class="barwrap" style="margin-top:4px"><div class="bar" style="width:${v}%"></div></div></td>`).join('')
        +`<td class="num"><strong>${fmtPct(avg)}</strong></td></tr>`;
    });
    box.innerHTML=h+'</table>';
    return;
  }
  const data=SHEET_DistrictData.rows.filter(r=>r[1]===state.year)
    .map(r=>({d:r[0],n:val(r,ind.numerator),dm:val(r,ind.denominator),v:cov(r,ind)}))
    .sort((a,b)=>b.v-a.v);
  let h=`<table><tr><th>#</th><th>District</th><th class="num">${esc(ind.numerator)}</th><th class="num">${esc(ind.denominator)}</th><th class="num">Coverage</th><th style="min-width:170px">Chart</th></tr>`;
  data.forEach((x,i)=>{
    h+=`<tr${i===0?' class="top"':''}><td><span class="rank">${i+1}</span></td><td><strong>${esc(x.d)}</strong></td>`
      +`<td class="num">${x.n.toLocaleString()}</td><td class="num">${x.dm.toLocaleString()}</td>`
      +`<td class="num"><strong>${fmtPct(x.v)}</strong><div class="calc">${x.n.toLocaleString()} ÷ ${x.dm.toLocaleString()} × 100 = ${x.v.toFixed(1)}%</div></td>`
      +`<td><div class="barwrap"><div class="bar" style="width:${x.v}%"></div></div></td></tr>`;
  });
  box.innerHTML=h+'</table>';
}
function renderRawData(ind){
  const all=SHEET_DistrictData.rows;
  const rows=state.year==='all'?all:all.filter(r=>r[1]===state.year);
  let h='<table><tr>'+COLS.map(c=>{
    let b='';
    if(c===ind.numerator)b=' <span class="badge num">numerator</span>';
    if(c===ind.denominator)b=' <span class="badge den">denominator</span>';
    return `<th class="${(c===ind.numerator||c===ind.denominator)?'num':''}">${esc(c)}${b}</th>`;
  }).join('')+'</tr>';
  h+=rows.map(r=>'<tr>'+r.map((v,i)=>`<td class="${i>1?'num':''}">${v}</td>`).join('')+'</tr>').join('');
  $('rawData').innerHTML=h+'</table>';
  $('srcFootnote').textContent=state.year==='all'
    ?`All ${rows.length} rows of the sheet shown (${DISTRICTS.length} districts × ${YEARS.length} years).`
    :`${rows.length} of ${all.length} rows, filtered to year ${state.year}.`;
}
function renderNotes(ind){
  let h='<table><tr>'+SHEET_IndicatorNotes.columns.map(c=>`<th>${esc(c)}</th>`).join('')+'</tr>';
  h+=SHEET_IndicatorNotes.rows.map(r=>
    `<tr class="${r[0]===ind.label?'top':''}">`+r.map(v=>`<td>${v==null?'—':esc(v)}</td>`).join('')+'</tr>'
  ).join('');
  $('notesSheet').innerHTML=h+'</table>';
}
function renderFormula(ind){
  const targetYear=state.year==='all'?YEARS[YEARS.length-1]:state.year;
  const row=SHEET_DistrictData.rows.find(r=>r[0]===DISTRICTS[0]&&r[1]===targetYear);
  const n=val(row,ind.numerator),d=val(row,ind.denominator);
  $('formulaCard').innerHTML=
    `<p><strong>${esc(ind.label)}</strong> — ${esc(ind.definition)}</p>`
    +`<div class="formula">${esc(ind.formula)}</div>`
    +`<p class="footnote">Unit: ${esc(ind.unit)} &middot; defined in sheet &ldquo;${SHEET_IndicatorNotes.name}&rdquo; (source column: ${esc(ind.source)})</p>`
    +`<p class="calc">Worked example — ${esc(row[0])}, ${row[1]}: &nbsp; ${n.toLocaleString()} ÷ ${d.toLocaleString()} × 100 = <strong>${(n/d*100).toFixed(1)}%</strong></p>`;
}
function render(){
  const ind=INDICATORS[state.ind];
  $('compareTitle').textContent=`${ind.label} — ${state.year==='all'?'trend (all years)':state.year}`;
  renderComparison(ind);
  renderFormula(ind);
  renderRawData(ind);
  renderNotes(ind);
}
render();

