function renderComparison(ind){
  const box=$('comparison');
  const ds=selDistricts();
  if(!ds.length){box.innerHTML='<p class="footnote">Select at least one district above.</p>';return;}
  if(state.year==='all'){
    const deltaCol=YEARS.length>1;
    let h='<table><tr><th>District</th>'+YEARS.map(y=>`<th class="num">${y}</th>`).join('')+'<th class="num">avg</th>'
      +(deltaCol?`<th class="num">Δ ${YEARS[0]}→${YEARS[YEARS.length-1]} (pp)</th>`:'')+'</tr>';
    ds.forEach(d=>{
      const rows=SHEET_DistrictData.rows.filter(r=>r[0]===d).sort((a,b)=>a[1]-b[1]);
      const vs=rows.map(r=>cov(r,ind));
      const avg=vs.reduce((s,v)=>s+v,0)/vs.length;
      const delta=vs[vs.length-1]-vs[0];
      h+=`<tr><td><strong>${esc(d)}</strong></td>`
        +vs.map(v=>`<td class="num">${fmtPct(v)}<div class="barwrap" style="margin-top:4px"><div class="bar" style="width:${v}%"></div></div></td>`).join('')
        +`<td class="num"><strong>${fmtPct(avg)}</strong></td>`
        +(deltaCol?`<td class="num"><span class="pp ${ppCls(delta)}">${pp(delta)}</span></td>`:'')
        +'</tr>';
    });
    box.innerHTML=h+'</table>';
    return;
  }
  const prevYear=YEARS.filter(y=>y<state.year).sort((a,b)=>b-a)[0];
  const data=ds.map(d=>{
    const r=SHEET_DistrictData.rows.find(r=>r[0]===d&&r[1]===state.year);
    const pr=prevYear?SHEET_DistrictData.rows.find(r=>r[0]===d&&r[1]===prevYear):null;
    return{d,n:val(r,ind.numerator),dm:val(r,ind.denominator),v:cov(r,ind),prev:pr?cov(pr,ind):null};
  }).sort((a,b)=>b.v-a.v);
  let h=`<table><tr><th>#</th><th>District</th><th class="num">${esc(ind.numerator)}</th><th class="num">${esc(ind.denominator)}</th><th class="num">Coverage</th><th style="min-width:170px">Chart</th></tr>`;
  data.forEach((x,i)=>{
    const delta=x.prev==null?null:x.v-x.prev;
    const deltaHtml=delta==null?'':`<div class="calc">Δ vs ${prevYear}: <span class="pp ${ppCls(delta)}">${pp(delta)}</span></div>`;
    h+=`<tr${i===0?' class="top"':''}><td><span class="rank">${i+1}</span></td><td><strong>${esc(x.d)}</strong></td>`
      +`<td class="num">${x.n.toLocaleString()}</td><td class="num">${x.dm.toLocaleString()}</td>`
      +`<td class="num"><strong>${fmtPct(x.v)}</strong><div class="calc">${x.n.toLocaleString()} ÷ ${x.dm.toLocaleString()} × 100 = ${x.v.toFixed(1)}%</div>${deltaHtml}</td>`
      +`<td><div class="barwrap"><div class="bar" style="width:${x.v}%"></div></div></td></tr>`;
  });
  box.innerHTML=h+'</table>';
}

