// ---- CSV export of the current comparison table ----
const csvCell=s=>{s=String(s);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};
function buildComparisonCSV(){
  const ind=INDICATORS[state.ind];
  const ds=selDistricts();
  if(!ds.length)return null;
  const L=[
    ['Indicator',ind.label],
    ['Formula',ind.formula],
    ['Unit',ind.unit],
    ['Source','maternal_health.xlsx, sheet "District Data"']
  ].map(p=>p.map(csvCell).join(','));
  L.push('');
  if(state.year==='all'){
    L.push(['district',...YEARS.map(y=>y+' (percent)'),'avg (percent)',`change ${YEARS[0]} to ${YEARS[YEARS.length-1]} (percentage points)`].map(csvCell).join(','));
    ds.forEach(d=>{
      const rows=SHEET_DistrictData.rows.filter(r=>r[0]===d).sort((a,b)=>a[1]-b[1]);
      const vs=rows.map(r=>cov(r,ind));
      const avg=vs.reduce((s,v)=>s+v,0)/vs.length;
      const delta=vs[vs.length-1]-vs[0];
      L.push([d,...vs.map(v=>v.toFixed(1)),avg.toFixed(1),(delta>0?'+':'')+delta.toFixed(1)].map(csvCell).join(','));
    });
  }else{
    const prevYear=YEARS.filter(y=>y<state.year).sort((a,b)=>b-a)[0];
    L.push(['rank','district',ind.numerator,ind.denominator,'coverage (percent)','calculation',prevYear?('change vs '+prevYear+' (percentage points)'):''].map(csvCell).join(','));
    const data=ds.map(d=>{
      const r=SHEET_DistrictData.rows.find(r=>r[0]===d&&r[1]===state.year);
      const pr=prevYear?SHEET_DistrictData.rows.find(r=>r[0]===d&&r[1]===prevYear):null;
      const n=val(r,ind.numerator),dm=val(r,ind.denominator),v=cov(r,ind);
      return{d,n,dm,v,delta:pr?v-cov(pr,ind):null};
    }).sort((a,b)=>b.v-a.v);
    data.forEach((x,i)=>L.push([i+1,x.d,x.n,x.dm,x.v.toFixed(1),x.n+' / '+x.dm+' * 100',x.delta==null?'':(x.delta>0?'+':'')+x.delta.toFixed(1)].map(csvCell).join(',')));
  }
  return L.join('\r\n');
}
function downloadComparisonCSV(){
